#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_stripeDirDeg;
uniform float amzp_stripeMag;
uniform float amzp_phaseStart;
uniform float amzp_phaseSpeed;
uniform float amzp_offset;
uniform float amzp_freqColors;
uniform float amzp_freqRed;
uniform float amzp_freqGreen;
uniform float amzp_freqBlue;
uniform float amzp_phaseRed;
uniform float amzp_phaseGreen;
uniform float amzp_phaseBlue;
uniform float amzp_brightness;
layout(color) uniform half4 amzp_tintColor;
uniform float amzp_saturation;
uniform float amzp_edgeAmt;
uniform float amzp_edgeWarp;
uniform float amzp_edgeWidth;
uniform float amzp_edgeInvert;
uniform float amzp_mixWithSource;

    float2 getResolution(){
      float2 s = getTexSize((screen.zw/1.0));
      if (s.x <= 0.0 || s.y <= 0.0) s = float2(1920.0, 1080.0);
      return s;
    }
    float gray(float4 c){ return dot(c.rgb, float3(0.299,0.587,0.114)); }
    float2x2 rot2(float a){ float c=cos(a), s=sin(a); return float2x2(c,-s,s,c); }

    float getLuma(float2 uv) {
      return gray(amzTexture(0, uv));
    }

    float sobel(float2 uv, float2 pixel, float w) {
      float2 p = pixel * w;
      float t00 = getLuma(uv + p * float2(-1, -1));
      float t10 = getLuma(uv + p * float2( 0, -1));
      float t20 = getLuma(uv + p * float2( 1, -1));
      float t01 = getLuma(uv + p * float2(-1,  0));
      float t21 = getLuma(uv + p * float2( 1,  0));
      float t02 = getLuma(uv + p * float2(-1,  1));
      float t12 = getLuma(uv + p * float2( 0,  1));
      float t22 = getLuma(uv + p * float2( 1,  1));
      float gx = t00 + 2.0 * t01 + t02 - (t20 + 2.0 * t21 + t22);
      float gy = t00 + 2.0 * t10 + t20 - (t02 + 2.0 * t12 + t22);
      return length(float2(gx, gy));
    }

    void amzRender(){
      float2 res = getResolution();
      float2 uv = amzScreenNorm();
      float2 pixel = 1.0 / res;

      float ang = radians(amzp_stripeDirDeg);
      float2 dir = rot2(ang) * float2(1.0, 0.0);


      float edge = sobel(uv, pixel, amzp_edgeWidth) * amzp_edgeAmt;
      float maskEdge = clamp(edge, 0.0, 1.0);
      if((amzp_edgeInvert>0.5)) maskEdge = 1.0 - maskEdge;

      float4 s0 = amzTexture(0, uv);
      float amp = gray(s0);

      float basePhase = amzp_phaseStart + time * amzp_phaseSpeed + amzp_offset;
      float mag = amzp_stripeMag;


      float wave = dot(uv - 0.5, dir) * mag + basePhase;
      wave += edge * amzp_edgeWarp;
      wave += amp * amzp_edgeWarp * 0.5;

      float fBase = amzp_freqColors;
      float rC = 0.5 + 0.5 * sin(wave * fBase * amzp_freqRed + amzp_phaseRed);
      float gC = 0.5 + 0.5 * sin(wave * fBase * amzp_freqGreen + amzp_phaseGreen);
      float bC = 0.5 + 0.5 * sin(wave * fBase * amzp_freqBlue + amzp_phaseBlue);
      float3 colS = float3(rC, gC, bC);

      float3 tint = amzp_tintColor.rgb;
      float3 colT = colS * tint;


      if(!(amzp_edgeInvert>0.5)) {
          colT *= (1.0 - maskEdge * 0.8); 
      } else {
          colT += maskEdge * 0.5; 
      }

      float g = dot(colT, float3(0.299,0.587,0.114));
      float3 colSat = mix(float3(g), colT, clamp(amzp_saturation, 0.0, 2.0));
      colSat *= amzp_brightness;

      float3 srcCol = s0.rgb;
      float aIn = s0.a;
      float3 stripeBlend = mix(colSat, srcCol, amzp_mixWithSource);
      float3 outCol = mix(srcCol, stripeBlend, aIn);

      amzOutput = float4(outCol, aIn);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

